/* Order topping game: local fixed-step simulation, one final proof submission. */
(()=>{'use strict';
function start(body,c,onFinish){
body.innerHTML='<section class="mq-order-game"><div class="mq-order-intro"><small>KKUWANG’S SWEET ORDER</small><h3>주문대로 톡톡, 나만의 빼빼로</h3><p>딸기와 아몬드는 골라 받고, 탄 초콜릿은 피해 주세요.</p></div><div class="mq-order-tickets"><div data-kind="strawberry"><i>🍓</i><span>딸기<strong>0 / 3</strong></span></div><div data-kind="almond"><i>🥜</i><span>아몬드<strong>0 / 3</strong></span></div><div class="mq-order-risk"><span>탄 초콜릿<strong>0 / 3</strong></span></div><div class="mq-order-clock">30.0<small>초</small></div></div><div class="mq-order-arena"><canvas width="800" height="500" tabindex="0" aria-label="좌우 방향키, A D 또는 마우스와 터치로 빼빼로를 움직여 주문 토핑을 받으세요"></canvas><div class="mq-order-start"><strong>꾸왕이의 주문서</strong><p>딸기 10개 + 아몬드 10개<br>30초 안에 완성 · 탄 초콜릿 3번이면 실패</p><button type="button">주문 받고 시작</button></div><span class="mq-order-combo"></span><span class="mq-order-size">빼빼로 길이 100%</span></div><div class="mq-order-cheer"><img src="assets/guide-kkuwang-detective-v1.png" alt="꾸왕이"><p role="status">필요한 토핑을 골라 줘! 일반 토핑은 더 받아도 괜찮아.</p></div><p class="mq-order-help">← → / A D 이동 · 마우스/터치로 이동 · 화면의 목표 수량을 채우면 즉시 완성</p></section>';
const game=body.querySelector('.mq-order-game'),canvas=game.querySelector('canvas'),ctx=canvas.getContext('2d'),button=game.querySelector('button'),keys=new Set(),counts={strawberry:0,almond:0},positions=[400],landed=new Set(),decor=[],effects=[];
const items=c.drops,byTick=new Map();for(const d of items){if(!byTick.has(d.landTick))byTick.set(d.landTick,[]);byTick.get(d.landTick).push(d);}
let x=400,goal=400,tick=0,burnt=0,combo=0,best=0,origin=null,ended=false,disposed=false,frameId,shakeUntil=0;
const radius=()=>Math.max(22,c.catchRadius-burnt*(c.shrinkPx||0)),half=()=>radius()+5;
game.querySelector('.mq-order-start p').innerHTML='딸기 '+c.order.strawberry+'개 + 아몬드 '+c.order.almond+'개<br>'+c.durationMs/1000+'초 안에 완성 · 탄 초콜릿 '+c.burnLimit+'번이면 실패 · 잘못 받으면 길이가 줄어요';
const names={strawberry:'딸기',almond:'아몬드',sprinkle:'스프링클',burnt:'탄 초콜릿'};
function say(s){game.querySelector('.mq-order-cheer p').textContent=s;}
function update(){for(const kind of Object.keys(counts)){const e=game.querySelector('[data-kind="'+kind+'"]');e.querySelector('strong').textContent=Math.min(counts[kind],c.order[kind])+' / '+c.order[kind];e.classList.toggle('done',counts[kind]>=c.order[kind]);}game.querySelector('.mq-order-risk strong').textContent=burnt+' / '+c.burnLimit;game.querySelector('.mq-order-risk').classList.toggle('danger',burnt>=2);game.querySelector('.mq-order-size').textContent='빼빼로 길이 '+Math.round(radius()/c.catchRadius*100)+'%';game.querySelector('.mq-order-combo').textContent=combo>=2?combo+' COMBO!':'';game.querySelector('.mq-order-clock').firstChild.textContent=Math.max(0,(c.durationMs-tick*c.tickMs)/1000).toFixed(1);}
function settle(){if(ended)return;ended=true;keys.clear();const success=Object.keys(counts).every(k=>counts[k]>=c.order[k])&&burnt<c.burnLimit;say(success?'완성! 주문에 딱 맞는 빼빼로야. 이제 예쁘게 포장하자!':burnt>=c.burnLimit?'앗, 탄 초콜릿이 너무 많아졌어. 새 빼빼로로 다시 해 보자!':'시간이 다 됐어! 다음에는 아직 부족한 토핑부터 골라 보자.');void onFinish({success,positions});}
function step(){tick++;if(keys.has('left')||keys.has('right'))goal=Math.max(85,Math.min(715,x+((keys.has('right')?1:0)-(keys.has('left')?1:0))*c.stepPx));x=Math.round(Math.max(85,Math.min(715,x+Math.max(-c.stepPx,Math.min(c.stepPx,goal-x))))*100)/100;positions.push(x);
for(const d of byTick.get(tick)||[]){landed.add(d.id);if(Math.abs(d.x-x)>radius()){if(d.kind in counts&&counts[d.kind]<c.order[d.kind])combo=0;continue;}effects.push({at:tick*c.tickMs,x:d.x,kind:d.kind});if(d.kind==='burnt'){burnt++;combo=0;shakeUntil=performance.now()+240;say(burnt>=c.burnLimit?'앗! 다음에는 검은 토핑을 피해 보자.':'탄 초콜릿이야! '+(c.burnLimit-burnt)+'번 더 받으면 실패해. 받는 길이도 줄었어!');}else{decor.push({kind:d.kind,offset:Math.max(-half()+8,Math.min(half()-8,d.x-x)),lane:decor.length%3});if(d.kind in counts){const needed=counts[d.kind]<c.order[d.kind];counts[d.kind]++;if(needed){combo++;best=Math.max(best,combo);say(combo>=3?'좋아! '+combo+'연속! 빼빼로가 점점 예뻐지고 있어.':names[d.kind]+' 토핑 성공! 부족한 토핑을 확인해 줘.');}else say(names[d.kind]+'는 충분해! 다른 토핑을 찾아보자.');}else say('스프링클도 예쁘네! 주문 수량에는 포함되지 않아.');}}
update();if(Object.keys(counts).every(k=>counts[k]>=c.order[k])||burnt>=c.burnLimit||tick*c.tickMs>=c.durationMs)settle();}
function symbol(kind,px,py,size=1){ctx.save();ctx.translate(px,py);ctx.scale(size,size);ctx.lineWidth=1.5;if(kind==='strawberry'){ctx.fillStyle='#eb7594';ctx.strokeStyle='#a73e60';ctx.beginPath();ctx.moveTo(0,13);ctx.bezierCurveTo(-26,-2,-15,-20,0,-10);ctx.bezierCurveTo(15,-20,26,-2,0,13);ctx.fill();ctx.stroke();ctx.fillStyle='#fff0b7';for(const [a,b] of [[-6,-3],[5,-4],[0,4]])ctx.fillRect(a,b,2,3);ctx.fillStyle='#698b5b';ctx.fillRect(-5,-15,10,5);}else if(kind==='almond'){ctx.fillStyle='#e8b97d';ctx.strokeStyle='#9c683c';ctx.beginPath();ctx.ellipse(0,0,10,16,.5,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(-4,10);ctx.lineTo(4,-10);ctx.stroke();}else if(kind==='burnt'){ctx.fillStyle='#443837';ctx.strokeStyle='#291f24';ctx.beginPath();ctx.moveTo(-13,-8);ctx.lineTo(6,-13);ctx.lineTo(15,6);ctx.lineTo(0,14);ctx.lineTo(-14,5);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#e28472';ctx.beginPath();ctx.moveTo(-4,-4);ctx.lineTo(4,4);ctx.moveTo(4,-4);ctx.lineTo(-4,4);ctx.stroke();ctx.strokeStyle='#907b76';for(let i=0;i<2;i++){ctx.beginPath();ctx.moveTo(-4+i*8,-17);ctx.quadraticCurveTo(-9+i*8,-24,-2+i*8,-29);ctx.stroke();}}else{for(let i=0;i<4;i++){ctx.fillStyle=['#f3bc6d','#b695ce','#f19bb8','#8ab8a2'][i];ctx.save();ctx.rotate(i*.8);ctx.fillRect(-2,-11,4,10);ctx.restore();}}ctx.restore();}
function draw(now){if(disposed)return;if(origin!==null&&!ended){let n=0;while(tick<Math.floor((now-origin)/c.tickMs)&&!ended&&n++<601)step();}const t=origin===null?0:Math.min(c.durationMs,now-origin);ctx.clearRect(0,0,800,500);const bg=ctx.createLinearGradient(0,0,0,500);bg.addColorStop(0,'#fff7e7');bg.addColorStop(1,'#e8c5b0');ctx.fillStyle=bg;ctx.fillRect(0,0,800,500);ctx.fillStyle='#f0d5bd';for(let i=0;i<8;i++)ctx.fillRect(i*110,0,2,500);ctx.fillStyle='#8b5d58';ctx.fillRect(0,0,800,13);ctx.fillStyle='#f6dfa8';for(let i=0;i<13;i++){ctx.beginPath();ctx.arc(30+i*62,14,4,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#b78380';ctx.fillRect(0,467,800,33);ctx.fillStyle='#eecba2';ctx.fillRect(0,467,800,3);ctx.save();ctx.translate(0,now<shakeUntil?Math.sin(now*.09)*3:0);ctx.fillStyle='#8f675640';ctx.beginPath();ctx.ellipse(x,465,half()+6,6,0,0,Math.PI*2);ctx.fill();ctx.lineCap='round';ctx.lineWidth=22;ctx.strokeStyle='#ddb376';ctx.beginPath();ctx.moveTo(x-half(),445);ctx.lineTo(x+half(),445);ctx.stroke();ctx.strokeStyle='#69432f';ctx.beginPath();ctx.moveTo(x-half()+20,445);ctx.lineTo(x+half(),445);ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#ad7c51';ctx.beginPath();ctx.moveTo(x-half()+23,438);ctx.lineTo(x+half()-7,438);ctx.stroke();for(const d of decor.slice(-28))symbol(d.kind,x+Math.max(-half()+8,Math.min(half()-8,d.offset)),442+d.lane*3,.28);ctx.restore();if(origin!==null){for(const d of items){if(landed.has(d.id)||t<d.atMs)continue;const p=(t-d.atMs)/d.travelMs;if(p>1.1)continue;symbol(d.kind,(d.startX??d.x)+(d.x-(d.startX??d.x))*Math.min(1,p),-18+p*463,1);}
for(let i=effects.length-1;i>=0;i--){const e=effects[i],age=t-e.at;if(age>600){effects.splice(i,1);continue;}ctx.save();ctx.globalAlpha=1-age/600;ctx.font='bold 16px "Malgun Gothic"';ctx.textAlign='center';ctx.fillStyle=e.kind==='burnt'?'#a04449':'#975067';ctx.fillText(e.kind==='burnt'?'앗!':'+1',e.x,420-age*.06);if(e.kind==='burnt'){ctx.fillStyle='#6c4130';for(const side of [-1,1]){ctx.save();ctx.translate(e.x+side*(30+age*.09),442+age*.05);ctx.rotate(side*age*.009);ctx.fillRect(-10,-4,20,8);ctx.restore();}}ctx.restore();}}
frameId=requestAnimationFrame(draw);}
function targetAt(e){const rect=canvas.getBoundingClientRect();goal=Math.max(85,Math.min(715,(e.clientX-rect.left)*800/rect.width));}
canvas.onpointerdown=e=>{targetAt(e);canvas.focus();if(e.pointerType==='touch')canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=targetAt;
function key(e,down){let k=window.CampusKeyboard?.key(e)||e.key.toLowerCase(),dir=['a','arrowleft'].includes(k)?'left':['d','arrowright'].includes(k)?'right':null;if(!dir)return;e.preventDefault();e.stopPropagation();if(down)keys.add(dir);else{keys.delete(dir);goal=x;}}
const kd=e=>key(e,true),ku=e=>key(e,false),blur=()=>{keys.clear();goal=x;};canvas.addEventListener('keydown',kd);canvas.addEventListener('keyup',ku);window.addEventListener('blur',blur);
button.onclick=()=>{if(origin!==null)return;origin=performance.now();game.querySelector('.mq-order-start').hidden=true;canvas.focus();say('딸기 '+c.order.strawberry+'개, 아몬드 '+c.order.almond+'개! 사선으로 떨어지는 토핑의 도착 위치를 봐 줘.');};update();frameId=requestAnimationFrame(draw);
return()=>{disposed=true;cancelAnimationFrame(frameId);keys.clear();canvas.removeEventListener('keydown',kd);canvas.removeEventListener('keyup',ku);window.removeEventListener('blur',blur);};
}
window.CampusToppingOrder={start};
})();
